begin;

-- Committees (upsert by slug) + drop the two placeholder committees from the first seed
delete from public.committees c where c.slug in ('media', 'finance')
  and not exists (select 1 from public.memberships m where m.committee_id = c.id)
  and not exists (select 1 from public.tasks t where t.committee_id = c.id);
insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('pm', 'PM', 'إدارة المشاريع التنموية', 'Project Management', 'لجنة إدارة المشاريع هي العمود الفقري لنشاط إيناكوس قنا. تتولى دراسة التحديات البيئية والاقتصادية في محافظة قنا وقرى الصعيد، وتحويلها إلى مشاريع ربحية مستدامة تخدم الفئات الأكثر احتياجاً وتلبي أهداف التنمية المستدامة للأمم المتحدة (SDGs).', '#16A34A', 'sprout', 1, true, false, '{"ar":{"brief":"العقل المفكر والمسؤول عن ابتكار وتطوير مشاريع ريادة الأعمال المجتمعية التي تحل مشاكل حقيقية في صعيد مصر.","mascot":"الفرعون صاحب التابلت الرقمي وخرائط الأثر","duties":["النزول الميداني لقرى ونجوع قنا لدراسة احتياجات المجتمع","إجراء دراسات الجدوى الاقتصادية والفنية للحلول المقترحة","تطبيق نماذج العمل التجاري (Business Model Canvas)","قياس مؤشرات الأثر المجتمعي والبيئي والمالي للمشاريع","إدارة خطوط الإنتاج والتشغيل وسلاسل الإمداد مع الحرفيين والمزارعين"],"skillsRequired":["التفكير التحليلي وحل المشكلات","أساسيات إدارة الأعمال ودراسات الجدوى","الشغف بالعمل الميداني والتطوعي في الصعيد","القدرة على العمل تحت الضغط وإدارة الأولويات"],"skillsGained":["إتقان إدارة المشاريع الاحترافية ومنهجيات Agile","مهارات متقدمة في قياس الأثر البيئي والاجتماعي (SROI)","بناء نماذج أعمال ريادية قابلة للتمويل والاستثمار"],"activeProjects":["مشروع نبتة (Nabta Green)","مشروع حرفة (Herfa Heritage)","مشروع شمس الجنوب"],"quote":"\"نحن لا ننتظر التغيير أن يحدث.. نحن نهندسه على أرض الواقع.\""},"en":{}}'::jsonb)
on conflict (slug) do update set
  code = excluded.code, name_ar = excluded.name_ar, name_en = excluded.name_en, description_ar = excluded.description_ar,
  color = excluded.color, icon = excluded.icon, sort_order = excluded.sort_order, is_public = excluded.is_public,
  is_media_team = excluded.is_media_team, content = excluded.content;
insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('multimedia', 'MULTI MEDIA', 'المالتي ميديا والتصميم', 'MultiMedia & Creative', 'لجنة المالتيميديا والتصميم مسؤولة عن ترجمة رسالة إيناكوس قنا إلى تجربة بصرية ساحرة، من خلال التصاميم ثلاثية الأبعاد، الهويات البصرية، تصوير الفعاليات وتغطية المشاريع الميدانية وصناعة الأفلام الوثائقية التي تُعرض أمام لجان تحكيم مسابقة الجمهورية NC.', '#7C3AED', 'clapperboard', 2, true, true, '{"ar":{"brief":"الفنانون وراء كل بوستر وهوية بصرية وفيديو يخطف الأنظار كما في حملات إيناكوس قنا الأسطورية.","mascot":"الفرعون المبدع بالنظارات والكاميرا الذهبية","duties":["تصميم الهويات البصرية والحملات الإعلانية (Branding & Posters)","تصوير وتوثيق الفعاليات والنزول الميداني والورش بجامعة جنوب الوادي","مونتاج وإنتاج الأفلام الوثائقية والفيديوهات الترويجية","تصميم الرسوم المتحركة ثلاثية الأبعاد (3D Animation & VFX)"],"skillsRequired":["حس فني وإبداعي وشغف بالبصريات","معرفة بأحد برامج أدوبي (Photoshop, Illustrator, Premiere) أو برامج 3D","القدرة على العمل في فريق واستقبال الملاحظات الفنية"],"skillsGained":["الاحتراف في بناء العلامات التجارية والحملات التسويقية","إتقان تقنيات الإخراج السينمائي والمونتاج المتقدم","صناعة بورتفوليو احترافي يؤهل لسوق العمل الدولي"],"activeProjects":["حملة From Qena to the World","فيلم توثيق معبد دندرة","هوية NC 2026"],"quote":"\"كل فكرة عظيمة تحتاج إلى لمسة إبداعية تمنحها الخلود.\""},"en":{}}'::jsonb)
on conflict (slug) do update set
  code = excluded.code, name_ar = excluded.name_ar, name_en = excluded.name_en, description_ar = excluded.description_ar,
  color = excluded.color, icon = excluded.icon, sort_order = excluded.sort_order, is_public = excluded.is_public,
  is_media_team = excluded.is_media_team, content = excluded.content;
insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('pr', 'PR', 'العلاقات العامة والشراكات', 'Public Relations & Partnerships', 'مسؤولة عن تمثيل إيناكوس قنا أمام المجتمع والجهات الرسمية، واستقطاب الرعايات (Sponsorships)، والتنسيق مع إدارة جامعة جنوب الوادي، وتوسيع شبكة العلاقات مع رواد الأعمال والشخصيات العامة.', '#2563EB', 'handshake', 3, true, false, '{"ar":{"brief":"الواجهة الرسمية لإيناكوس قنا وسفراء بناء الشراكات مع كبرى الشركات والجامعات والمؤسسات.","mascot":"الفرعون صاحب الميكروفون الذهبي والغمزة الواثقة","duties":["التفاوض وإبرام بروتوكولات الشراكات الاستراتيجية","إعداد ملفات الرعاية (Sponsorship Proposals) والتواصل مع الشركات","إدارة العلاقات الإعلامية والتغطية الصحفية","استقبال كبار الضيوف والمتحدثين في مؤتمرات الفريق"],"skillsRequired":["مهارات تواصل وتفاوض استثنائية وكاريزما عالية","لباقة في الحديث والإقناع والمراسلات الرسمية","اللغة الإنجليزية والعربية بطلاقة"],"skillsGained":["شبكة علاقات واسعة مع كبار المسؤولين ورجال الأعمال","إتقان فنون البيع المؤسسي (B2B) واستقطاب التمويل","مهارات البروتوكول والدبلوماسية والعلاقات العامة الاحترافية"],"activeProjects":["شراكة الاتحاد العربي للتدريب","شراكة YAFFA E-Marketing","تحالف رعاية NC"],"quote":"\"نبني جسور الثقة ونحفر اسم قنا في كل محفل.\""},"en":{}}'::jsonb)
