insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('oc', 'OC', 'لجنة التنظيم واللوجستيات', 'Organizing Committee', 'لجنة التنظيم هي صمام الأمان وراء نجاح جميع الفعاليات على أرض الواقع، بدءاً من حجز القاعات والتنسيق اللوجستي، وحتى إدارة حركة الجماهير وضمان انسيابية البرامج الزمنية دون أي خلل.', '#EA580C', 'calendar-check', 4, true, false, '{"ar":{"brief":"القوة الميدانية التي تدير كل إيفنت ومعسكر ومؤتمر بأعلى درجات النظام والانضباط.","mascot":"الفرعون صاحب البردية ومخططات التنفيذ","duties":["التخطيط الزمني واللوجستي للفعاليات والمؤتمرات","إدارة القاعات والمدرجات بجامعة جنوب الوادي وتجهيز المعدات","استقبال الحضور وإدارة تسجيل الدخول والتنظيم الميداني","التعامل الفوري والاحترافي مع الأزمات والمواقف الطارئة"],"skillsRequired":["سرعة البديهة والقدرة على حل المشكلات تحت الضغط","روح العمل الجماعي والانضباط في المواعيد","اللياقة العالية والجاهزية للعمل الميداني"],"skillsGained":["إدارة الفعاليات الضخمة والمهرجانات الطلابية (Event Management)","إدارة اللوجستيات والمخاطر وإدارة الحشود","القيادة الميدانية وبناء روح الفريق الواحد"],"activeProjects":["مؤتمر الانطلاقة السنوي","معسكر تدريب الصعيد","يوم التوظيف المفتوح"],"quote":"\"الانضباط هو الفارق بين الفوضى والأسطورة.\""},"en":{}}'::jsonb)
