insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('hr', 'HR', 'الموارد البشرية والتطوير', 'Human Resources & Talent', 'تهتم لجنة الموارد البشرية بالجانب الإنساني؛ من استقطاب المواهب، إجراء المقابلات، تقييم الأداء، وحتى حل النزاعات وتقديم برامج تدريبية ترفع من كفاءة كل فرد في الكتيبة.', '#0D9488', 'users', 5, true, false, '{"ar":{"brief":"حراس بيئة العمل وصناع القادة ومكتشفو المواهب الشابة.","mascot":"الفرعون الحكيم حامل سجلات التطوير البشري","duties":["تنظيم وإدارة حملات التوظيف ومقابلات الانضمام (Interviews)","متابعة أداء الأعضاء وتقييم الالتزام وفق مؤشرات (KPIs)","تنظيم ورش عمل التدريب والتطوير وجلسات الـ Team Building","نشر ثقافة التعاون والمحافظة على بيئة عمل محفزة وإيجابية"],"skillsRequired":["الذكاء العاطفي والاستماع الفعال","الحيادية والموضوعية والسرية التامة في التعامل مع البيانات","مهارات حل النزاعات والتحفيز المستمر"],"skillsGained":["إتقان ممارسات الموارد البشرية وفق المعايير العالمية","تقنيات التقييم النفسي والمهني وإجراء المقابلات الاحترافية","تصميم البرامج التدريبية ومسارات التطوير الوظيفي"],"activeProjects":["أكاديمية قادة إيناكوس قنا","نظام تقييم الأداء الشهري","معسكر تعزيز الفريق"],"quote":"\"أعظم استثمار هو الاستثمار في العقول والقلوب المخلصة.\""},"en":{}}'::jsonb)
