insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('presentation', 'PRESENTATION', 'فرسان المنصة والعرض', 'Presentation & Pitching', 'فريق الخطابة والعرض مسؤول عن إبهار لجان التحكيم في المسابقة الوطنية، بنقل قصة كفاح ومشاريع وأثر إيناكوس قنا بأسلوب قصصي ملهم باللغتين الإنجليزية والعربية.', '#DC2626', 'mic', 6, true, false, '{"ar":{"brief":"صوت الفريق في المسابقة الوطنية المصرية وأمام لجان التحكيم وكبار المستثمرين.","mascot":"الفرعون الخطيب متحدث المنصة وناقل الحلم","duties":["كتابة ومراجعة نصوص العروض التقديمية (Scriptwriting)","التدريب المكثف على لغة الجسد ونبرات الصوت وسرعة الإلقاء","تمثيل الفريق على المسرح في المسابقة الوطنية السنوية NC","إدارة جلسات الأسئلة والأجوبة (Q&A) الصعبة مع كبار الحكام ورجال الأعمال"],"skillsRequired":["طلاقة تامة في التحدث أمام الجمهور بدون تردد","إجادة ممتازة للغة الإنجليزية والعربية","حضور مسرحي قوي وثقة عالية بالنفس"],"skillsGained":["الاحتراف في فنون الخطابة العامة (Public Speaking) والـ Storytelling","القدرة على إقناع المستثمرين وصناديق التمويل بأي فكرة","بناء كاريزما استثنائية تؤهل للقيادة في أي محفل دولي"],"activeProjects":["العرض الختامي لمسابقة الجمهورية NC 2026","سلسلة لقاءات TEDx SVU"],"quote":"\"على المنصة، تتحول أرقام المشاريع إلى نبضات تلهب حماس القلوب.\""},"en":{}}'::jsonb)
