insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)
values ('social', 'SOCIAL MEDIA', 'صناع المحتوى والسوشيال ميديا', 'Social Media & Marketing', 'المسؤولون عن قيادة المنصات الرقمية لإيناكوس قنا (فيسبوك، إنستجرام، لينكد إن)، ونشر قصص الأثر والترويج للفعاليات واستقطاب المتابعين والداعمين.', '#DB2777', 'megaphone', 7, true, true, '{"ar":{"brief":"We don''t just post, we purpose! صوت قنا الرقمي وصانعو المحتوى الهادف الملهم.","mascot":"مبتكرو الرسالة والطيارات الورقية الذهبية","duties":["صياغة خطط النشر الأسبوعية والشهرية واستراتيجيات المحتوى","كتابة النصوص الإبداعية (Copywriting & Storytelling)","إدارة التفاعل والرد على الرسائل والتعليقات وبناء مجتمع رقمي قوي","تحليل مؤشرات الوصول والـ Analytics وإطلاق الحملات الممولة"],"skillsRequired":["شغف بكتابة المحتوى الإبداعي وفهم خوارزميات السوشيال ميديا","متابعة أحدث الـ Trends وتوظيفها بذكاء ورقي","سرعة الاستجابة وروح المبادرة"],"skillsGained":["إتقان إدارة العلامات التجارية على وسائل التواصل الاجتماعي","تحليل البيانات الرقمية وتحسين معدلات التحويل والانتشار العضوي","بناء مجتمعات رقمية ولائية تتفاعل مع قضايا المجتمع"],"activeProjects":["حملة Leave Your Mark","سلسلة يوميات مشروع بالصعيد","بودكاست حكايات إيناكوس"],"quote":"\"لا نكتب كلمات عابرة.. نحن نصيغ رسائل تزرع الأمل في النفوس.\""},"en":{}}'::jsonb)
