-- Events (upsert by slug). upcoming -> published, past -> completed
insert into public.events (season_id, slug, title_ar, title_en, description_ar, brief_ar, venue_ar, starts_at, ends_at, status, cover_url, is_public, registration_open, category_ar, time_label_ar, schedule, partner_names)
values ((select id from public.seasons where is_active limit 1), 'nc-orientation-2026', 'المؤتمر التحضيري لمسابقة الجمهورية NC 2026', 'National Competition Orientation Camp', 'تنظم إيناكوس جامعة جنوب الوادي المؤتمر السنوي الأضخم لإطلاق خطة خوض المسابقة الوطنية Enactus Egypt National Competition. يشهد المؤتمر حضور نخبة من أساتذة الجامعة، رواد الأعمال، والشركاء الرسميين.', 'لقاء انطلاق الاستعدادات لمسابقات ريادة الأعمال على مستوى جامعات مصر، ومراجعة جاهزية مشاريع قنا التنموية.', 'قاعة المؤتمرات الكبرى - جامعة جنوب الوادي، قنا', (timestamp '2026-11-15 10:00:00' at time zone 'Africa/Cairo'), (timestamp '2026-11-15 16:00:00' at time zone 'Africa/Cairo'), 'published', '/assets/E9.jpg', true, false, 'مؤتمرات رسمية', '10:00 صباحاً - 04:00 مساءً', '[{"time_ar":"10:00 ص","activity_ar":"تسجيل الحضور واستلام الحقائب التعريفية"},{"time_ar":"11:00 ص","activity_ar":"كلمة افتتاحية من رئيس الفريق وإدارة الجامعة"},{"time_ar":"12:30 م","activity_ar":"عرض تقديمي شامل لملفات المشاريع المستدامة"},{"time_ar":"02:00 م","activity_ar":"جلسة حوارية مع الشركاء والرعاة الرسميين"},{"time_ar":"03:30 م","activity_ar":"تكريم المتميزين وإعلان خطة العمل الميداني"}]'::jsonb, '["الاتحاد العربي للتدريب والتنمية","YAFFA E-Marketing","جامعة جنوب الوادي"]'::jsonb)
