values ((select id from public.seasons where is_active limit 1), 'social-entrepreneurship-bootcamp', 'معسكر ريادة الأعمال المجتمعية لشباب الصعيد', 'Upper Egypt Social Innovation Bootcamp', 'فرصة فريدة لأعضاء الفريق والطلاب المتميزين لخوض تجربة محاكاة واقعية لبناء شركة ناشئة تعالج مشكلة بيئية في صعيد مصر، مع الحصول على شهادات معتمدة.', 'معسكر تدريبي مكثف يقدمه خبراء الاتحاد العربي للتدريب لتأهيل الطلاب على صياغة الحلول التنموية وخطط الأعمال.', 'مركز المؤتمرات والتدريب - مجمع كليات قنا', (timestamp '2026-12-02 09:00:00' at time zone 'Africa/Cairo'), (timestamp '2026-12-03 17:00:00' at time zone 'Africa/Cairo'), 'published', '/assets/partner_arab_union.png', true, false, 'ورش تدريبية ومعسكرات', '09:00 صباحاً - 05:00 مساءً (لمدة يومين)', '[{"time_ar":"اليوم الأول","activity_ar":"توليد الأفكار وتحليل سلاسل القيمة ومشاكل المجتمع"},{"time_ar":"اليوم الثاني","activity_ar":"بناء النموذج الأولي (Prototype) وفنون العرض والتمويل"}]'::jsonb, '["الاتحاد العربي للتدريب والتنمية","الأوائل لتنمية المهارات"]'::jsonb)
