values ((select id from public.seasons where is_active limit 1), 'dendera-heritage-exhibition', 'معرض دندرة للتراث الأخضر والصناعات الحرفية', 'Dendera Green Heritage Fair', 'احتفالية مجتمعية مبهجة جمعت مئات المواطنين والحرفيين لعرض المنتجات التراثية بعد إعادة تصميمها وتسويقها، والتي حققت مبيعات قياسية دعمت أكثر من 150 أسرة منتجة.', 'عرض مخرجات مشروع حِرفة لتمكين سيدات قرى قنا في صناعة الفخار والخزف الصديق للبيئة.', 'ساحة معبد دندرة ومركز التنمية المستدامة، قنا', (timestamp '2026-09-20 10:00:00' at time zone 'Africa/Cairo'), null, 'completed', '/assets/E1.jpg', true, false, 'معارض ميدانية', 'انتهت الفعالية بنجاح', '[{"time_ar":"11:00 ص","activity_ar":"افتتاح المعرض واستقبال ممثلي وزارة التضامن"},{"time_ar":"01:00 م","activity_ar":"ورشة حية لتشكيل الفخار القناوي بالتقنيات الحديثة"},{"time_ar":"04:00 م","activity_ar":"توقيع عقود توريد مع منصات التجارة الإلكترونية"}]'::jsonb, '["VERANDA","مكتبات الرضا","YAFFA E-Marketing"]'::jsonb)
