values ((select id from public.seasons where is_active limit 1), 'recruitment-launch-2026', 'يوم التوظيف المفتوح: Leave Your Mark', 'Annual Recruitment Drive', 'شهد الحرم الجامعي أجواء أسطورية بتوزيع البروشورات والبطاقات التعريفية بمشاركة تميمة الفراعنة، وإقبال استثنائي من طلاب كليات الهندسة، التجارة، العلوم، الحاسبات والآداب.', 'استقبال أكثر من 1,200 طلب انضمام من مختلف كليات جامعة جنوب الوادي وإجراء المقابلات الشخصية.', 'الساحة المركزية - جامعة جنوب الوادي', (timestamp '2026-10-10 10:00:00' at time zone 'Africa/Cairo'), null, 'completed', '/assets/E7.jpg', true, false, 'استقطاب وتوظيف', 'انتهت الفعالية', '[{"time_ar":"طوال اليوم","activity_ar":"استقبال استمارات المتقدمين وإجراء المقابلات الأولية"}]'::jsonb, '["VERANDA","مكتبات الرضا"]'::jsonb)
