-- News (upsert by slug)
insert into public.news_posts (slug, title_ar, excerpt_ar, body_ar, cover_url, category_ar, is_published, published_at)
values ('partnership-arab-union-announced', 'توقيع بروتوكول تعاون استراتيجي مع الاتحاد العربي للتدريب والتنمية', 'في خطوة تاريخية تهدف لتعزيز كفاءة شباب الصعيد، وقعت إيناكوس جامعة جنوب الوادي بروتوكول تعاون تدريبي وتأهيلي رائد مع الاتحاد العربي للتدريب والتنمية.', 'أعلنت إدارة إيناكوس قنا رسمياً توقيع بروتوكول تعاون مشترك مع الاتحاد العربي للتدريب والتنمية تحت شعار "Together, We Create Greater Impact". يهدف البروتوكول إلى تزويد أعضاء لجان الفريق ببرامج تدريبية تخصصية معتمدة دولياً في مجالات إدارة المشاريع المستدامة، التسويق الرقمي، القيادة وفنون الإلقاء، بما يرفع جاهزية الفريق للمنافسة في بطولة كأس مصر لريادة الأعمال الجامعية.', '/assets/partner_arab_union.png', 'شراكات استراتيجية', true, (timestamp '2026-10-24 12:00:00' at time zone 'Africa/Cairo'))
on conflict (slug) do update set
  title_ar = excluded.title_ar, excerpt_ar = excluded.excerpt_ar, body_ar = excluded.body_ar, cover_url = excluded.cover_url,
  category_ar = excluded.category_ar, is_published = excluded.is_published, published_at = excluded.published_at;
insert into public.news_posts (slug, title_ar, excerpt_ar, body_ar, cover_url, category_ar, is_published, published_at)
values ('sponsors-cohort-2026-revealed', 'الإعلان عن باقة الرعاة الرسميين لمسيرة إيناكوس قنا لعام 2026', 'كشف الفريق عن الرعاة الرسميين الذين يقدمون دعماً لوجستياً وتدريبياً وخدمياً متكاملاً: فراندة، الاتحاد العربي، الأوائل لتنمية المهارات، ومكتبات الرضا.', 'أزاح فريق إيناكوس قنا الستار عن باقة رعاته الرسميين لموسم 2026، معرباً عن فخره بالثقة المتبادلة مع كبرى المؤسسات والكيانات بقنا. يقدم الرعاة تسهيلات شاملة تتضمن رعاية الضيافة في VERANDA، والاعتماد التدريبي مع الاتحاد العربي، وصقل القدرات مع الأوائل، وتجهيز المواد الدعائية والمطبوعات مع مكتبات الرضا.', '/assets/sponsors_list.png', 'رعايات ودعم', true, (timestamp '2026-10-22 12:00:00' at time zone 'Africa/Cairo'))
on conflict (slug) do update set
  title_ar = excluded.title_ar, excerpt_ar = excluded.excerpt_ar, body_ar = excluded.body_ar, cover_url = excluded.cover_url,
  category_ar = excluded.category_ar, is_published = excluded.is_published, published_at = excluded.published_at;
insert into public.news_posts (slug, title_ar, excerpt_ar, body_ar, cover_url, category_ar, is_published, published_at)
values ('dendera-jersey-reveal', 'إطلاق القميص الرسمي المستوحى من معبد دندرة: From Qena To The World', 'بتصميم يمزج بين عمارة معبد دندرة التاريخي وألوان إيناكوس الذهبية والرمادية، أطلق الفريق قميصه الرسمي الذي أثار إعجاب الآلاف على منصات التواصل.', 'تحت شعار "من قلب الصعيد، حيث كُتب التاريخ على الحجر، نحمل رؤيتنا لنعبر بها الحدود"، دشنت إيناكوس قنا قميص الفريق الرسمي لموسم 2026. يحمل القميص نقوش أعمدة معبد دندرة ورمز القوة والتحدي في صورة فنية ساحرة لاقت تفاعلاً واسعاً عبر صفحة الفيسبوك الرسمية.', '/assets/E9.jpg', 'الهوية البصرية', true, (timestamp '2026-10-15 12:00:00' at time zone 'Africa/Cairo'))
on conflict (slug) do update set
  title_ar = excluded.title_ar, excerpt_ar = excluded.excerpt_ar, body_ar = excluded.body_ar, cover_url = excluded.cover_url,
  category_ar = excluded.category_ar, is_published = excluded.is_published, published_at = excluded.published_at;
insert into public.news_posts (slug, title_ar, excerpt_ar, body_ar, cover_url, category_ar, is_published, published_at)
values ('nabta-project-milestone', 'مشروع نبتة يحقق وفراً بيئياً بتدوير 50 طناً من مخلفات القصب بقنا', 'نجح طلاب إيناكوس قنا في تحويل أطنان من سفير القصب إلى ألواح بيئية وسماد عضوي، متفادين حرقها ومعززين دخل المزارعين المحليين.', 'سجل مشروع نبتة، أحد المشاريع الريادية الرائدة لإيناكوس جامعة جنوب الوادي، إنجازاً بيئياً واقتصادياً لافتاً في الموسم الزراعي الحالي، بتمكين العشرات من مزارعي محافظة قنا من الاستفادة من مخلفات قصب السكر بديلاً عن الحرق المكشوف، وتحويلها إلى منتجات ذات قيمة تجارية عالية.', '/assets/E4.jpg', 'إنجازات المشاريع', true, (timestamp '2026-10-05 12:00:00' at time zone 'Africa/Cairo'))
on conflict (slug) do update set
  title_ar = excluded.title_ar, excerpt_ar = excluded.excerpt_ar, body_ar = excluded.body_ar, cover_url = excluded.cover_url,
  category_ar = excluded.category_ar, is_published = excluded.is_published, published_at = excluded.published_at;

-- FAQ (replaced as a whole)
delete from public.faqs;
insert into public.faqs (question_ar, answer_ar, sort_order) values ('ما هو نشاط Enactus وما الذي يميز فرع جامعة جنوب الوادي بقنا؟', 'إيناكوس (Enactus) هي منظمة دولية رائدة غير ربحية تجمع بين الطلاب وقادة الأعمال والأكاديميين لتحويل الأفكار إلى مشاريع ريادة أعمال مجتمعية مستدامة. ويتميز فرع جامعة جنوب الوادي بقنا بارتباطه الوثيق بقضايا صعيد مصر وتراث معبد دندرة، وتطوير حلول حقيقية تلائم بيئة الجنوب وتصعد للمنافسة في مسابقة الجمهورية وكأس العالم.', 1);
insert into public.faqs (question_ar, answer_ar, sort_order) values ('هل يُشترط أن أكون طالباً في كلية معينة للانضمام؟', 'لا على الإطلاق! التقديم مفتوح لجميع طلاب كليات جامعة جنوب الوادي بقنا (تجارة، هندسة، علوم، حاسبات، آداب، تربية، زراعة، طب، صيدلة، تمريض، وغيرها). كل تخصص يضيف قيمة فريدة للكتيبة.', 2);
insert into public.faqs (question_ar, answer_ar, sort_order) values ('هل أحتاج لخبرة سابقة للقبول في لجان مثل المالتيميديا أو الـ PR؟', 'لا نطلب خبرة سابقة إلزامية. معيارنا الأساسي هو الشغف، الجدية، والرغبة الصادقة في التعلم وخدمة المجتمع. نوفر من خلال لجاننا ورعاتنا (كالاتحاد العربي للتدريب) ورش عمل تدريبية تصقل مهاراتك من الصفر وحتى الاحتراف.', 3);
insert into public.faqs (question_ar, answer_ar, sort_order) values ('كيف تتم مراحل التقديم والاختيار؟', 'تبدأ بملء استمارة التقديم الإلكترونية (Join Us)، ثم مراجعة الاستمارات من قِبل لجنة الـ HR، يليها تحديد موعد للمقابلة الشخصية (Personal Interview) الودية للتعرف على شخصيتك وطموحاتك، ثم إعلان المقبولين في معسكر الانطلاقة.', 4);
insert into public.faqs (question_ar, answer_ar, sort_order) values ('كيف يمكن للشركات والمؤسسات رعاية نشاط إيناكوس قنا؟', 'يمكنكم التواصل مباشرة مع لجنة العلاقات العامة من خلال صفحة "كن راعياً / Become a Sponsor" أو مراسلتنا عبر صفحة فيسبوك الرسمية. نقدم باقات رعاية متنوعة تشمل الظهور الإعلامي في فعاليات الجامعة، الترويج على السوشيال ميديا (أكثر من 11,700 متابع)، والتواجد في بوسترات مسابقة الجمهورية NC.', 5);
insert into public.faqs (question_ar, answer_ar, sort_order) values ('ما الاستفادة الشخصية التي تعود عليّ كعضو في الفريق؟', 'ستكتسب خبرة عملية تسبق بها زملاءك بسنوات: إدارة مشاريع حقيقية، بناء شبكة علاقات مع كبرى الشركات، مهارات العمل الجماعي والقيادة، شهادات معتمدة، وأولوية في فرص التدريب والتوظيف بعد التخرج.', 6);

-- Sponsorship tiers (replaced by name). The public label replaces a price on purpose.
